import{_ as t}from"./chunks/gather-evidence.CFBdlZLj.js";import{_ as a}from"./chunks/test-case-detail.C5uQxYLf.js";import{_ as r,o,c as s,ak as n}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Failure evidence","description":"Everything captured about one failing execution on one screen: the evidence tabs, clues, attempts, the page diff and the trace-powered views.","frontmatter":{"title":"Failure evidence","description":"Everything captured about one failing execution on one screen: the evidence tabs, clues, attempts, the page diff and the trace-powered views.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/evidence.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/evidence.html"}],["meta",{"property":"og:title","content":"Failure evidence | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Everything captured about one failing execution on one screen: the evidence tabs, clues, attempts, the page diff and the trace-powered views."}]]},"headers":[],"relativePath":"features/evidence.md","filePath":"features/evidence.md","lastUpdated":1791017030000}'),i={name:"features/evidence.md"};function h(d,e,c,l,g,p){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="failure-evidence" tabindex="-1">Failure evidence <a class="header-anchor" href="#failure-evidence" aria-label="Permalink to &quot;Failure evidence&quot;">​</a></h1><p>When a test fails, everything Piwi captured about that attempt lands on one screen: what each tab holds, where it came from, and what a trace adds.</p><p>Two pages are involved, and <a href="/guide/concepts.html#execution">Core concepts</a> draws the line between them:</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>Answers</th></tr></thead><tbody><tr><td><strong>Execution</strong></td><td><code>/test-run-cases/:id</code></td><td>&quot;why did this attempt fail?&quot;: <a href="#one-execution-diagnosis-first">the diagnosis view</a></td></tr><tr><td><strong>Test case</strong></td><td><code>/test-cases/:id</code></td><td>&quot;how has this test behaved over time?&quot;: <a href="#the-test-case-page">its history</a></td></tr></tbody></table><p>Links from a run land on an execution; the test&#39;s title links to its test case.</p><h2 id="one-execution-diagnosis-first" tabindex="-1">One execution, diagnosis-first <a class="header-anchor" href="#one-execution-diagnosis-first" aria-label="Permalink to &quot;One execution, diagnosis-first&quot;">​</a></h2><p>A failing execution reads top to bottom in one column. It opens on the <strong>situation block</strong> (the headline, the most likely cause, the situation and the next step), described once on <a href="/guide/first-failure.html">Your first failure, explained</a>. Traces stream in while the run is still running.</p><figure><img src="'+t+'" alt="A failing execution: one situation block, then one evidence card whose tabs (Timeline, Screen, Source, Network, Console, State, Performance) hold the captured evidence"><figcaption>A failing execution: the situation block, then one evidence card whose tabs hold everything captured.</figcaption></figure><p>Below the block, one <strong>evidence card</strong> holds tabs, each with a count or a dot when it holds data. It opens on <strong>Source</strong> or <strong>Performance</strong> when a strong or medium leading clue cites it, else on <strong>Timeline</strong> when it can place two or more items, else on the cited tab, else on <strong>Screen</strong> when a screenshot or video exists, else on <strong>Source</strong>; never on <strong>State</strong>.</p><ul><li><strong>Timeline</strong>: one time axis for the steps, console entries, requests, their backend logs and (Playwright 1.63+) browser dialogs, with the failure marked, over a steps table giving each step&#39;s offset (<code>t-1.1s</code>) and duration. <strong>Around the failure</strong> / <strong>Whole test</strong> and one chip per item type filter both. Hooks and fixtures fold into <strong>Setup</strong> and <strong>Teardown</strong> rows, open when the failure is there; a <code>test.step</code> holds its steps; the step that raised the test&#39;s error shows its error and its page&#39;s Screenshot, DOM and Accessibility tree; a caught error is greyed out.</li><li><strong>Attempts</strong>: shown when a test ran more than once, see <a href="#attempts">below</a>.</li><li><strong>Screen</strong>: the page at the failure as views (<strong>Screenshot</strong>, <strong>DOM</strong>, <strong>Accessibility tree</strong>, <strong>Visual diff</strong>, <a href="#page-diff"><strong>Page diff</strong></a>, <strong>Video</strong>) over the trace and attachments. <strong>Open in picker</strong> finds a locator on that DOM from any view.</li><li><strong>Source</strong>: the test source as a call stack (the line that threw plus its callers), deepened <a href="#trace-powered-deep-views">with a trace</a>.</li><li><strong>Network</strong>: the requests with inline <a href="/guide/backend-logs.html">backend logs</a>; one with no response shows the browser&#39;s error (<code>net::ERR_CONNECTION_RESET</code>). <strong>Console</strong>: the console output. <strong>State</strong>: the app state at test end and the environment diff against the last green run. <strong>Performance</strong>: performance hints and Web Vitals.</li></ul><p>Below the evidence sit the folded <a href="./fix-plans.html#more-ways-to-fix"><strong>More ways to fix</strong></a> toolbox and a <strong>history</strong> strip of this test&#39;s recent executions. A <strong>passing</strong> execution shows the identity and facts lines only, with the evidence card on <strong>Timeline</strong>. Network, console, Web Vitals, ARIA and alternative-locator data come from the <a href="/guide/capture-fixtures.html">capture fixtures</a>.</p><h3 id="clues" tabindex="-1">Clues <a class="header-anchor" href="#clues" aria-label="Permalink to &quot;Clues&quot;">​</a></h3><p>A <strong>clue</strong> is a one-line finding a deterministic rule draws from the evidence already captured, with no model involved. Each carries a <strong>strength</strong> (strong, medium or weak) and a <strong>citation</strong> to the evidence section it came from, so a click jumps to the proof; the <strong>Most likely</strong> line leads with the story they form, else a completed diagnosis, else the strongest one, and the AI diagnosis receives them as evidence. Every rule, and when it fires, is listed on <a href="/reference/clues.html">Clue rules</a>.</p><h3 id="attempts" tabindex="-1">Attempts <a class="header-anchor" href="#attempts" aria-label="Permalink to &quot;Attempts&quot;">​</a></h3><p>When a test failed and then passed on retry, the <strong>Attempts</strong> tab lists every attempt (status and duration, the one you opened marked), then <strong>what differed</strong> between the failing attempt and the passing one, most diagnostic first:</p><ul><li>the <strong>error</strong> present on the failing attempt and gone on the pass;</li><li>a <strong>request</strong>, keyed by route (<code>GET /api/cart/:id</code>), that failed (5xx or no response) on one attempt only, or took at least 1 s and twice as long on the failing one;</li><li>a <strong>console</strong> error or warning logged on one attempt only;</li><li>a <strong>step</strong> that errored, ran much slower, or ran with different <strong>params</strong> on one attempt;</li><li>a <strong>page-state or URL</strong> difference, including storage keys and cookies;</li><li>an <strong>ARIA structural</strong> difference at the landmark and heading level.</li></ul><p>Each difference links to its evidence tab, a request that is one of the test&#39;s <a href="./flaky-tests.html#suspects">suspects</a> to it. The comparison feeds the <a href="./flaky-tests.html#root-cause-classification">root-cause classifier</a>.</p><h2 id="page-diff" tabindex="-1">Page diff <a class="header-anchor" href="#page-diff" aria-label="Permalink to &quot;Page diff&quot;">​</a></h2><p>Where the visual diff compares pixels, the Screen tab&#39;s <strong>Page diff</strong> view compares <em>structure</em>: it parses the failing page&#39;s <a href="/guide/capture-fixtures.html#what-gets-captured">ARIA snapshot</a> and the same test&#39;s last passing snapshot into trees and reports nodes <strong>added</strong>, <strong>removed</strong>, <strong>renamed</strong>, <strong>changed</strong> (an attribute such as <code>[disabled]</code> flipped) or <strong>moved</strong>, with a <code>+3 −1 ~2</code> summary. The element the failing locator names is highlighted: a broken <code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; })</code> lands on the button renamed <code>&quot;Pay now&quot;</code>.</p><p>The baseline is the same test&#39;s most recent passing snapshot on the same browser, preferring the same environment then the same branch. Green snapshots come from <a href="/guide/capture-fixtures.html#green-page-sampling-on-pass">sampling on pass</a>, about once a day per test; until one exists the view says why (<em>not captured</em>, <em>no green sample yet</em> or <em>not applicable</em>). The page-diff summary reaches the <code>explain_failure</code> <a href="/features/mcp.html">MCP tool</a>.</p><p>When the trace carries <a href="#aria-and-screen-snapshots">aria snapshots</a>, the view adds an <strong>in-execution</strong> page diff that needs no green baseline: the structure at the failure against the last different page before the failing action.</p><h2 id="trace-powered-deep-views" tabindex="-1">Trace-powered deep views <a class="header-anchor" href="#trace-powered-deep-views" aria-label="Permalink to &quot;Trace-powered deep views&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Screenshots are Playwright&#39;s to record</p><p>Failure screenshots come from Playwright&#39;s <code>screenshot: &#39;only-on-failure&#39;</code> <code>use</code> option. Playwright&#39;s default is <code>&#39;off&#39;</code>: with the option unset, the evidence has video and traces but no screenshot. See <a href="/guide/reporter.html#basic-configuration">Basic configuration</a>.</p></div><p>With an uploaded trace (<code>trace: &#39;retain-on-failure&#39;</code> or <code>&#39;on-first-retry&#39;</code>), two views go deeper:</p><ul><li><strong>Source → Full stack</strong>: the complete call stack of the failing action, every frame with its real source from the trace, dependency frames folded, and Open in IDE on each frame in your project.</li><li><strong>Network → Full trace</strong>: every request the page made, on a waterfall with the failing action&#39;s window shaded, with timing phases, headers and a capped body preview. Sensitive headers and token-shaped strings are masked on the server.</li></ul><h3 id="aria-and-screen-snapshots" tabindex="-1">Aria and screen snapshots <a class="header-anchor" href="#aria-and-screen-snapshots" aria-label="Permalink to &quot;Aria and screen snapshots&quot;">​</a></h3><p>A Playwright 1.63 trace can record the page&#39;s <strong>aria tree</strong> and a <strong>screenshot</strong> before and after every action (<code>trace: { snapshots: { dom, aria, screen } }</code>; <a href="/guide/reporter.html#installing-via-wrapconfig"><code>wrapConfig</code></a> turns <code>aria</code> on, <code>screen</code> stays <a href="/operate/storage.html#trace-snapshots">opt-in</a>). Then the Screenshot view sets the page <strong>before the failing action</strong> beside the one at the failure, and the Timeline tab adds a <strong>filmstrip</strong> of the page before each step. The <a href="#page-diff">in-execution page diff</a> reads the same snapshots.</p><h3 id="recovered-from-the-trace-without-the-fixtures" tabindex="-1">Recovered from the trace without the fixtures <a class="header-anchor" href="#recovered-from-the-trace-without-the-fixtures" aria-label="Permalink to &quot;Recovered from the trace without the fixtures&quot;">​</a></h3><p>With the reporter alone and a trace uploaded, the dashboard recovers the <strong>console</strong> entries, the <strong>network requests</strong> (including the failed and aborted ones) and the failure-time <strong>ARIA snapshot</strong> from the trace at ingest. Cards showing this data carry a <strong>derived from the trace</strong> chip, and fixture-captured data is never replaced.</p><h3 id="why-a-card-is-empty" tabindex="-1">Why a card is empty <a class="header-anchor" href="#why-a-card-is-empty" aria-label="Permalink to &quot;Why a card is empty&quot;">​</a></h3><p>A tab that needs the capture fixtures appears only when it holds data or the fixtures ran and found nothing; otherwise one footer line names the missing tabs. When a card does open empty, it says which case applies: <strong>captured, nothing happened</strong>, <strong>not applicable</strong> (backend logs need a <a href="/guide/backend-logs.html">backend integration</a>), or <strong>declined</strong> for this project (<a href="/operate/capabilities.html#declining-a-capability">Declining a capability</a>). The AI diagnosis&#39;s <strong>Data coverage</strong> block uses the same words.</p><h2 id="trace-viewer" tabindex="-1">Trace viewer <a class="header-anchor" href="#trace-viewer" aria-label="Permalink to &quot;Trace viewer&quot;">​</a></h2><p><strong>Open trace</strong>, at the top of the evidence card on every tab, opens the full Playwright trace viewer, the same UI as <code>npx playwright show-trace</code>; the Screen tab lists each trace with <strong>Open trace</strong> and <strong>Download</strong>. The dashboard serves the viewer at <code>/trace-viewer/</code>, so traces never go to a third party, with or without <a href="/operate/authentication.html">authentication</a>. The hosted <code>trace.playwright.dev</code> cannot send your session cookie, so it only works against a dashboard with authentication off.</p><h2 id="the-test-case-page" tabindex="-1">The test case page <a class="header-anchor" href="#the-test-case-page" aria-label="Permalink to &quot;The test case page&quot;">​</a></h2><p><code>/test-cases/:id</code> is the other axis: not one attempt, but the test&#39;s whole life. Total runs, pass rate, average duration and last run, a duration trend, a status-history strip, and the recent executions, each linking back to its execution. A flaky test adds a <strong>Flakiness</strong> tab with its <a href="./flaky-tests.html#suspects">suspects</a>.</p><figure><img src="'+a+'" alt="Test case page with run stats above a duration trend chart, a status history strip, and a table of recent executions"><figcaption>The test case page: pass rate and duration stats, a duration trend, and every recent execution of this test.</figcaption></figure><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/first-failure.html">Your first failure, explained</a>: the situation block at the top of a failing execution</li><li><a href="/recipes/broken-locator.html">Fix a broken locator</a>: this page, used for one concrete job</li><li><a href="/reference/clues.html">Clue rules</a>: every rule behind a clue</li><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: the one file that produces the network, console, Web Vitals and locator evidence</li><li><a href="./ai-diagnosis.html">AI diagnosis</a>: an explanation of the failure against your git diff</li><li><a href="./offline-export.html">Offline export</a>: take the investigation out of the dashboard as one file</li></ul>',38)])])}const b=r(i,[["render",h]]);export{w as __pageData,b as default};
